changeSet.sql:
ALTER TABLE subscription
    DROP COLUMN IF EXISTS adapters;

ALTER TABLE subscription
    ADD COLUMN IF NOT EXISTS adapter_config_ids JSONB NOT NULL DEFAULT '[]'::jsonb,
    ADD COLUMN IF NOT EXISTS organization_id BIGINT NULL;

ALTER TABLE subscription
    ADD CONSTRAINT fk_subscription_organization
    FOREIGN KEY (organization_id) REFERENCES organization(id) ON DELETE CASCADE;

DROP INDEX IF EXISTS idx_subscription_watchlist_user;

CREATE UNIQUE INDEX IF NOT EXISTS idx_subscription_personal_unique
    ON subscription (watchlist_id, user_id)
    WHERE organization_id IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS idx_subscription_org_unique
    ON subscription (watchlist_id, user_id, organization_id)
    WHERE organization_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_subscription_organization_id
    ON subscription (organization_id);

COMMENT ON COLUMN subscription.adapter_config_ids IS 'JSON array of adapter config UUIDs to use for notification delivery';
COMMENT ON COLUMN subscription.organization_id IS 'Optional organization this subscription belongs to (NULL for personal subscriptions)';
COMMENT ON INDEX idx_subscription_personal_unique IS 'Unique index ensuring one personal subscription per user per watchlist';
COMMENT ON INDEX idx_subscription_org_unique IS 'Unique index ensuring one org subscription per user per watchlist per org';
COMMENT ON INDEX idx_subscription_organization_id IS 'Index for finding subscriptions by organization';
